static const BounceScriptSet script_sets[] = {
    { "ZH_CN", ZH_CN_glyphs,
      (unsigned int)(sizeof ZH_CN_glyphs / sizeof ZH_CN_glyphs[0]),
      11, 10, BOUNCE_LANGUAGE_ZH_CN },
    { "ZH_TW", ZH_TW_glyphs,
      (unsigned int)(sizeof ZH_TW_glyphs / sizeof ZH_TW_glyphs[0]),
      11, 10, BOUNCE_LANGUAGE_ZH_TW },
    { "TH_TH", TH_TH_glyphs,
      (unsigned int)(sizeof TH_TH_glyphs / sizeof TH_TH_glyphs[0]),
      11, 9, BOUNCE_LANGUAGE_TH_TH },
};

#define BOUNCE_SCRIPT_SET_COUNT (sizeof script_sets / sizeof script_sets[0])

static BounceLanguage script_active_language = BOUNCE_LANGUAGE_EN;

void bounce_script_font_set_active_language(BounceLanguage language)
{
    if ((int)language < 0 || (int)language >= (int)BOUNCE_LANGUAGE_COUNT)
        return;
    script_active_language = language;
}

BounceLanguage bounce_script_font_active_language(void)
{
    return script_active_language;
}

static const BounceScriptSet *active_set(void)
{
    unsigned int i;

    for (i = 0u; i < BOUNCE_SCRIPT_SET_COUNT; ++i) {
        if (script_sets[i].language == script_active_language)
            return &script_sets[i];
    }
    /* EN and ID are pure Latin and use the 5x7 font, so there is no set. */
    return NULL;
}

const BounceScriptMetrics *bounce_script_font_metrics(void)
{
    /* One object, refilled on each call: the sets are const, and a caller
     * must never be able to write through the returned pointer. */
    static BounceScriptMetrics current;
    const BounceScriptSet *set = active_set();

    current.cell_width = BOUNCE_SCRIPT_CELL_WIDTH;
    current.cell_height = BOUNCE_SCRIPT_CELL_HEIGHT;
    if (set == NULL) {
        current.advance = 0;
        current.baseline = 0;
    } else {
        current.advance = set->advance;
        current.baseline = set->baseline;
    }
    return &current;
}

const BounceScriptGlyph *bounce_script_font_lookup(const char *utf8,
    int length)
{
    const BounceScriptSet *set = active_set();
    char key[BOUNCE_SCRIPT_KEY_BYTES];
    unsigned int i;
    int j;

    if (set == NULL || utf8 == NULL)
        return NULL;
    /* length is the caller's cluster length, not a scan to the NUL. */
    if (length <= 0 || length >= (int)BOUNCE_SCRIPT_KEY_BYTES)
        return NULL;
    for (j = 0; j < length; ++j)
        key[j] = utf8[j];
    key[length] = '\0';

    /*
     * A LINEAR scan on purpose.
     *
     * A binary search would need the table sorted in exactly the order
     * strcmp() implies, and strcmp() compares char, which is signed on this
     * target: every UTF-8 byte above 0x7F compares as negative. A table
     * generated in unsigned byte order is therefore NOT sorted in strcmp
     * order, and the search silently misses most clusters. That is exactly
     * what happened here. A linear scan cannot depend on an ordering
     * assumption at all, and at a few hundred entries the cost is
     * irrelevant for a 128x128 UI.
     */
    for (i = 0u; i < set->count; ++i) {
        if (strcmp(set->glyphs[i].utf8, key) == 0)
            return &set->glyphs[i];
    }
    return NULL;
}

unsigned int bounce_script_font_glyph_count(void)
{
    const BounceScriptSet *set = active_set();

    return set == NULL ? 0u : set->count;
}
